def insert_ticket(data: TicketCreate) -> Ticket:
    """Insert a new ticket with open status and return its record."""
    def insert(db):
        cur = db.execute(
            "INSERT INTO tickets (title, priority, status) VALUES (?, ?, ?)",
            (data.title, data.priority, "open"),
        )
        return Ticket(id=cur.lastrowid, title=data.title, priority=data.priority, status="open")

    return run_db(insert)

@router.get("", response_model=list[Ticket])
def list_tickets(status: Literal["open", "closed"] | None = None) -> list[Ticket]:
    """List all tickets, or filter by an accepted status."""
    return read_tickets(status)

def read_tickets(status: str | None) -> list[Ticket]:
    """Return newest first, optionally restricted to one status."""
    def select(db):
        query = "SELECT id, title, priority, status FROM tickets"
        params = ()
        if status is not None:
            query += " WHERE status = ?"
            params = (status,)
        return [Ticket(**dict(row)) for row in db.execute(query + " ORDER BY id DESC", params)]

    return run_db(select)

